/**
 * 漢字的中文字義與用例。**這個檔案是手寫的。**
 *
 * 和 dict.ts 分開放是刻意的：dict.ts 是 KANJIDIC2 的衍生資料（CC BY-SA），
 * 重跑產生器會整份覆蓋；這裡的中譯是本專案自己的成果，重跑不會被動到。
 *
 * **一個字給 2〜4 個詞，而且要是「不同用法」。**
 * 只給一個詞看不出這個字在做什麼 —— 就像「安」在中文裡有安心也有安裝，
 * 日文的安同時出現在 安心{あんしん}（音読み）和 安{やす}い（訓読み），
 * 兩種讀法、兩種意思。用例要讓這件事自己浮出來。
 *
 * 日文欄用振り仮名標記（`安{やす}い`），讀音由 `readingOf()` 推導，
 * 不另存一個 reading 欄位 —— 存兩份遲早會對不上。
 *
 * **不是每個字都會有。** 還沒寫到的在畫面上標「中譯未補」，缺口要看得見。
 */

